# codemod: raw hex -> nearest token (fuzzy), humans review ambiguous
tokens = {'text-primary': '#1a1a1a', 'surface': '#ffffff', 'accent': '#0066cc'}

def nearest(hexval):
    def dist(a, b):
        return sum(abs(int(a[i:i+2], 16) - int(b[i:i+2], 16)) for i in (1, 3, 5))
    return min(tokens, key=lambda t: dist(hexval, tokens[t]))

for raw in ('#1b1b1b', '#0066cc', '#ff0000'):
    tok = nearest(raw)
    flag = '' if raw != '#ff0000' else ' <- AMBIGUOUS: human review'
    print('%-8s -> var(--%s)%s' % (raw, tok, flag))
print('migrate per surface; lint ban on raw colors lands LAST')
